    '[{\"image\":\"/assets/images/areas/chhatarpur-farms.jpg\",\"caption\":\"Sprawling poolside terrace and lush private grounds in Chhatarpur Farms\"},{\"image\":\"/assets/images/stitch/service-hero-villa.jpg\",\"caption\":\"Contemporary country estate architecture with floor-to-ceiling glass pavilions\"},{\"image\":\"/assets/images/stitch/golf-links-pool-villa.jpg\",\"caption\":\"Manicured formal lawns and private swimming pavilion in a gated farmhouse enclave\"}]',
